// Next Imports
import { redirect } from 'next/navigation'

// Component Imports
import Register from '@views/register'
import PropertyListingWizard from '@views/property-listing'

// Type Imports
import { validRoles } from '@/types/userTypes'

// Roles that get the property listing wizard as their signup flow
const wizardRoles = ['property-manager', 'property-owner'] as const

type Props = {
  params: Promise<{ lang: string; role: string }>
}

const RegisterPage = async (props: Props) => {
  const params = await props.params
  const { role } = params

  // Redirect to select-role if invalid role
  if (!validRoles.includes(role as (typeof validRoles)[number])) {
    redirect(`/${params.lang}/select-role`)
  }

  const isWizardRole = wizardRoles.includes(role as (typeof wizardRoles)[number])

  if (isWizardRole) {
    return (
      <div className='flex justify-center items-center min-bs-dvh p-6'>
        <div className='max-is-[1200px] is-full'>
          <PropertyListingWizard />
        </div>
      </div>
    )
  }

  return (
    <div className='flex flex-col justify-center items-center min-bs-dvh p-6'>
      <Register role={role} />
    </div>
  )
}

export default RegisterPage
